663	// ManifestRecordError reports a manifest record that is structurally invalid
664	// or carries a quantity outside the accepted range. Position is the record's
665	// 1-based position in the manifest.
666	type ManifestRecordError struct {
667		Position int
668		Batch    string // normalized batch id when available, otherwise ""
669		Reason   string
670	}
