211				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
212				usage: batchRegisterUsage,
213			}
214		}
215	
216		batch, err := batchreg.NormalizeField(*batchRaw)
217		if err != nil {
218			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
219		}
