255			status = "created"
256		}
257		result := struct {
258			Batch    string `json:"batch"`
259			Product  string `json:"product"`
260			Quantity int64  `json:"quantity"`
261			Unit     string `json:"unit"`
262			Status   string `json:"status"`
263		}{
