9	// Directly submitted Input records must satisfy the same effective-value
10	// rules as single Register calls and parsed file records: the three text
11	// fields are non-empty valid UTF-8 and quantity is positive — regardless of
12	// whether the batch id is new, already stored or seen earlier in the same
13	// submission, so the validity check can never be skipped by the create,
14	// duplicate-confirmation or conflict branch.
15	func TestImportRejectsInvalidDirectRecords(t *testing.T) {
16		valid := func() Input { return Input{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"} }
17	
18		cases := []struct {
19			name      string
20			mutate    func(*Input)
21			wantField string
22		}{
23			{"empty batch", func(in *Input) { in.Batch = "" }, "batch"},
24			{"empty product", func(in *Input) { in.Product = "" }, "product"},
25			{"empty unit", func(in *Input) { in.Unit = "" }, "unit"},
26			{"quantity zero", func(in *Input) { in.Quantity = 0 }, "quantity"},
27			{"quantity negative", func(in *Input) { in.Quantity = -4 }, "quantity"},
28		}
29	
30		// Each scenario places the offending record where, before the fix, a
31		// different branch used to accept it or classify it as a conflict: a
32		// brand-new id, an id already stored (an empty text field would have
33		// looked like a registry conflict), and an id introduced earlier in the
34		// same submission. prepare aligns the record with the stored/earlier id
35		// before the mutation empties the batch field itself.
36		scenarios := []struct {
37			name    string
38			reg     []Batch
39			pos     int
40			prepare func(in *Input)
41			prefix  func() []Input // records preceding the bad one
42		}{
43			{
44				name:    "new id",
45				pos:     1,
46				prepare: func(in *Input) {},
47				prefix:  func() []Input { return nil },
48			},
49			{
50				name: "id already registered",
51				reg:  []Batch{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}},
52				pos:  2,
53				prepare: func(in *Input) {
54					in.Batch = "B1"
55					in.Product = "P-7"
56					in.Unit = "kg"
57				},
58				// Record 1 confirms the stored duplicate before record 2 fails.
59				prefix: func() []Input {
60					return []Input{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}}
61				},
62			},
63			{
64				name:    "id seen earlier in this submission",
65				pos:     2,
66				prepare: func(in *Input) { in.Batch = "B1" },
67				prefix: func() []Input {
68					return []Input{{Batch: "B1", Product: "P-7", Quantity: 10, Unit: "kg"}}
69				},
70			},
71		}
72	
73		for _, sc := range scenarios {
74			t.Run(sc.name, func(t *testing.T) {
75				for _, tc := range cases {
76					t.Run(tc.name, func(t *testing.T) {
77						reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), sc.reg...)}
78						bad := valid()
79						sc.prepare(&bad)
80						tc.mutate(&bad)
81						inputs := append(sc.prefix(), bad)
82	
83						results, err := Import(reg, inputs)
84						var re *ManifestRecordError
85						if !errors.As(err, &re) {
86							t.Fatalf("got %v, want ManifestRecordError", err)
87						}
88						var ce *ManifestConflictError
89						if errors.As(err, &ce) {
90							t.Fatalf("invalid record must not be reported as a conflict: %v", err)
91						}
92						if results != nil {
93							t.Fatalf("failed import must report no results, got %+v", results)
94						}
95						if re.Position != sc.pos {
96							t.Errorf("position=%d, want %d", re.Position, sc.pos)
97						}
98						if !strings.Contains(re.Reason, tc.wantField) {
99							t.Errorf("reason %q must name field %q", re.Reason, tc.wantField)
100						}
101						// Registry keeps exactly its pre-import content.
102						if len(reg.Batches) != len(sc.reg) {
103							t.Fatalf("rejected import mutated the registry: %+v", reg.Batches)
104						}
105						for i, b := range sc.reg {
106							if reg.Batches[i] != b {
107								t.Fatalf("rejected import mutated record %d: %+v", i+1, reg.Batches[i])
108							}
109						}
110					})
111				}
112			})
113		}
114	}
115	
116	// Validity is settled for every record before any conflict is weighed: an
117	// invalid record is the reported failure even when an earlier record already
118	// clashes with a stored record or with a record earlier in the same
119	// submission. Swapping the invalid record and the conflicting one only moves
120	// the reported position — the precedence never changes.
121	func TestImportInvalidRecordOutranksConflict(t *testing.T) {
122		stored := Batch{Batch: "B1", Product: "P1", Quantity: 10, Unit: "kg"}
123		cases := []struct {
124			name    string
125			inputs  []Input
126			wantPos int
127		}{
128			{
129				name: "registry conflict before invalid record",
130				inputs: []Input{
131					{Batch: "B1", Product: "P1", Quantity: 11, Unit: "kg"}, // conflicts with the stored record
132					{Batch: "B2", Product: "P2", Quantity: 1, Unit: ""},    // invalid
133				},
134				wantPos: 2,
135			},
136			{
137				name: "invalid record before registry conflict",
138				inputs: []Input{
139					{Batch: "B2", Product: "P2", Quantity: 1, Unit: ""},    // invalid
140					{Batch: "B1", Product: "P1", Quantity: 11, Unit: "kg"}, // would conflict with the stored record
141				},
142				wantPos: 1,
143			},
144			{
145				name: "same-submission conflict before invalid record",
146				inputs: []Input{
147					{Batch: "BX", Product: "P1", Quantity: 10, Unit: "kg"}, // would create
148					{Batch: "BX", Product: "P1", Quantity: 99, Unit: "kg"}, // conflicts with record 1
149					{Batch: "B2", Product: "P2", Quantity: 0, Unit: "kg"},  // invalid
150				},
151				wantPos: 3,
152			},
153			{
154				name: "first of several invalid records wins over earlier conflict",
155				inputs: []Input{
156					{Batch: "B1", Product: "P1", Quantity: 11, Unit: "kg"}, // conflicts with the stored record
157					{Batch: "B2", Product: "", Quantity: 1, Unit: "kg"},    // invalid
158					{Batch: "B3", Product: "P3", Quantity: -1, Unit: "kg"}, // invalid
159				},
160				wantPos: 2,
161			},
162		}
163		for _, tc := range cases {
164			t.Run(tc.name, func(t *testing.T) {
165				reg := &Registry{Version: FormatVersion, Batches: []Batch{stored}}
166				results, err := Import(reg, tc.inputs)
167				var re *ManifestRecordError
168				if !errors.As(err, &re) {
169					t.Fatalf("got %v, want ManifestRecordError", err)
170				}
171				var ce *ManifestConflictError
172				if errors.As(err, &ce) {
173					t.Fatalf("an invalid record must never be reported as a conflict: %v", err)
174				}
175				if re.Position != tc.wantPos {
176					t.Errorf("position=%d, want %d", re.Position, tc.wantPos)
177				}
178				if results != nil {
179					t.Errorf("failed import must report no results, got %+v", results)
180				}
181				if len(reg.Batches) != 1 || reg.Batches[0] != stored {
182					t.Errorf("rejected import mutated the registry: %+v", reg.Batches)
183				}
184			})
185		}
186	}
187	
188	// A late invalid record fails the whole submission even when the earlier
189	// records have already resolved as creates, same-submission duplicates and
190	// stored duplicates: nothing new may remain and the caller gets no partial
191	// result.
192	func TestImportLateInvalidRecordFailsWholeSubmission(t *testing.T) {
193		original := []Batch{{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"}}
194		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), original...)}
195		results, err := Import(reg, []Input{
196			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"}, // would create
197			{Batch: "NEW1", Product: "P-2", Quantity: 10, Unit: "box"}, // same-submission duplicate
198			{Batch: "OLD", Product: "P-1", Quantity: 3, Unit: "kg"},    // stored duplicate
199			{Batch: "NEW2", Product: "P-3", Quantity: 1, Unit: "m"},    // would create
200			{Batch: "NEW3", Product: "P-4", Quantity: 1, Unit: ""},     // invalid
201		})
202		var re *ManifestRecordError
203		if !errors.As(err, &re) {
204			t.Fatalf("got %v, want ManifestRecordError", err)
205		}
206		if re.Position != 5 || re.Batch != "NEW3" {
207			t.Fatalf("unexpected error position/batch: %+v", re)
208		}
209		if !strings.Contains(re.Reason, `"unit"`) {
210			t.Fatalf("reason must name field %q: %s", "unit", re.Reason)
211		}
212		if results != nil {
213			t.Fatalf("failed import must report no results, got %+v", results)
214		}
215		if len(reg.Batches) != 1 || reg.Batches[0] != original[0] {
216			t.Fatalf("rejected import left new batches in the registry: %+v", reg.Batches)
217		}
218	}
219	
220	// The batch id is cited only when the batch field itself is non-empty and
221	// valid UTF-8; an empty or malformed id is never invented or replaced. The
222	// offending field always rides in the reason text.
223	func TestImportInvalidRecordBatchAttachment(t *testing.T) {
224		fffd := string(rune(0xfffd))
225		cases := []struct {
226			name            string
227			in              Input
228			wantBatch       string
229			wantReasonField string
230		}{
231			{"empty batch", Input{Batch: "", Product: "P", Quantity: 1, Unit: "kg"}, "", "batch"},
232			{"invalid utf8 batch", Input{Batch: "B-\xff", Product: "P", Quantity: 1, Unit: "kg"}, "", "batch"},
233			{"empty product names batch", Input{Batch: "B7", Product: "", Quantity: 1, Unit: "kg"}, "B7", "product"},
234			{"empty unit names batch", Input{Batch: "B7", Product: "P", Quantity: 1, Unit: ""}, "B7", "unit"},
235			{"zero quantity names batch", Input{Batch: "B7", Product: "P", Quantity: 0, Unit: "kg"}, "B7", "quantity"},
236			{"bad product bytes names valid batch", Input{Batch: "B7", Product: "P\xff", Quantity: 1, Unit: "kg"}, "B7", "product"},
237			{"whitespace batch cited verbatim", Input{Batch: " B ", Product: "P", Quantity: 0, Unit: "kg"}, " B ", "quantity"},
238			{"genuine replacement char is a valid id", Input{Batch: fffd, Product: "P", Quantity: 0, Unit: "kg"}, fffd, "quantity"},
239		}
240		for _, tc := range cases {
241			t.Run(tc.name, func(t *testing.T) {
242				reg := &Registry{Version: FormatVersion}
243				_, err := Import(reg, []Input{tc.in})
244				var re *ManifestRecordError
245				if !errors.As(err, &re) {
246					t.Fatalf("got %v, want ManifestRecordError", err)
247				}
248				if re.Position != 1 {
249					t.Errorf("position=%d, want 1", re.Position)
250				}
251				if re.Batch != tc.wantBatch {
252					t.Errorf("batch=%q, want %q", re.Batch, tc.wantBatch)
253				}
254				if !strings.Contains(re.Reason, tc.wantReasonField) {
255					t.Errorf("reason %q must name field %q", re.Reason, tc.wantReasonField)
256				}
257				if tc.wantBatch == "" && strings.Contains(err.Error(), "(batch \"") {
258					t.Errorf("error must not cite a batch id: %v", err)
259				}
260				if tc.wantBatch != "" && !strings.Contains(err.Error(), `(batch "`+tc.wantBatch+`")`) {
261					t.Errorf("error must cite batch %q verbatim: %v", tc.wantBatch, err)
262				}
263				if len(reg.Batches) != 0 {
264					t.Fatalf("rejected import appended records: %+v", reg.Batches)
265				}
266			})
267		}
268	}
269	
270	// Direct submissions keep text verbatim: no trimming and no case folding.
271	// Edge and interior whitespace stay part of the value, so ids that differ
272	// only by such characters are different batches.
273	func TestImportKeepsDirectTextVerbatim(t *testing.T) {
274		reg := &Registry{Version: FormatVersion}
275		inputs := []Input{
276			{Batch: " B1 ", Product: " P 7 ", Quantity: 1, Unit: " kg "},
277			{Batch: " B1 ", Product: " P 7 ", Quantity: 1, Unit: " kg "}, // verbatim repeat -> duplicate
278			{Batch: "B1", Product: "P7", Quantity: 1, Unit: "kg"},        // distinct id and values
279		}
280		out, err := Import(reg, inputs)
281		if err != nil {
282			t.Fatal(err)
283		}
284		if len(out) != 3 || !out[0].Created || out[1].Created || !out[2].Created {
285			t.Fatalf("unexpected outcomes: %+v", out)
286		}
287		want := []Batch{
288			{Batch: " B1 ", Product: " P 7 ", Quantity: 1, Unit: " kg "},
289			{Batch: "B1", Product: "P7", Quantity: 1, Unit: "kg"},
290		}
291		for i, b := range want {
292			if reg.Batches[i] != b {
293				t.Errorf("stored record %d = %+v, want %+v", i+1, reg.Batches[i], b)
294			}
295		}
296	}
297	
298	// Whitespace-only text is a legal non-empty direct value: the no-trimming
299	// rule belongs to the direct path, and such a record is accepted the same
300	// way it would be through the single-record Register entry.
301	func TestImportAcceptsWhitespaceOnlyDirectText(t *testing.T) {
302		reg := &Registry{Version: FormatVersion}
303		in := Input{Batch: " ", Product: "\t", Quantity: 1, Unit: "\n"}
304		out, err := Import(reg, []Input{in, in})
305		if err != nil {
306			t.Fatalf("whitespace-only text is non-empty and must be accepted: %v", err)
307		}
308		if !out[0].Created || out[1].Created {
309			t.Fatalf("unexpected outcomes: %+v", out)
310		}
311		if len(reg.Batches) != 1 || reg.Batches[0].Batch != " " || reg.Batches[0].Product != "\t" || reg.Batches[0].Unit != "\n" {
312			t.Fatalf("text not kept verbatim: %+v", reg.Batches)
313		}
314	}
