1	package batchreg
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// This file guards the atomicity of Save when the save itself — not the
14	// validation phase and not a neighboring unusable path — fails on the file
15	// being replaced. Two mid-save failure points are covered, each injected
16	// deterministically through the package-level step variables:
17	//
18	//   - the content write into the temporary file stops before the new content
19	//     is complete;
20	//   - the new content is fully prepared on disk, but the final replacement of
21	//     the target file fails.
22	//
23	// In both cases the caller must get an error naming the target path and the
24	// cause, an existing target must keep its exact bytes and modification time
25	// and still load with its original records in order, a missing target must
26	// stay missing, no temporary file may survive, and the caller's submitted
27	// records must be left untouched. A success counterpart with the very same
28	// submission proves the protection is what keeps the old content in place,
29	// not a save that never ran. The injections need no disk fault, no special
30	// filesystem and no missing permissions, so they reproduce offline under any
31	// account, root included.
32	
33	// savedFailureRegistryJSON is the existing registry every failure scenario
34	// starts from: multiple batches, loaded back for comparison in their stored
35	// order.
36	const savedFailureRegistryJSON = `{"version":1,"batches":[` +
37		`{"batch":"OLD-1","product":"苹果","quantity":10,"unit":"kg"},` +
38		`{"batch":"OLD-2","product":"P-2","quantity":20,"unit":"box"},` +
39		`{"batch":"OLD-3","product":"P-3","quantity":30,"unit":"m"}]}`
40	
41	// failedSaveModTime is pinned onto the existing registry file so that any
42	// rewrite — even one restoring identical bytes — is visible as a changed
43	// modification time.
44	var failedSaveModTime = time.Date(2009, time.February, 13, 23, 31, 30, 0, time.UTC)
45	
46	// failureSubmission is a legal batch table under every existing field,
47	// quantity and id rule: the three stored records plus two clearly
48	// distinguishable new ones. It is what the caller hands to Save in every
49	// scenario of this file, failure and success alike.
50	func failureSubmission() []Batch {
51		return []Batch{
52			saveBatch("OLD-1", "苹果", 10, "kg"),
53			saveBatch("OLD-2", "P-2", 20, "box"),
54			saveBatch("OLD-3", "P-3", 30, "m"),
55			saveBatch("NEW-1", "新产品", 99, "箱"),
56			saveBatch("NEW-2", "P-new", MaxQuantity, " pallet "),
57		}
58	}
59	
60	// setupExistingRegistry writes the multi-batch registry, pins its modification
61	// time to failedSaveModTime and returns the target path, the original records
62	// in stored order and the original file bytes.
63	func setupExistingRegistry(t *testing.T) (dir, path string, original []Batch, originalBytes []byte) {
64		t.Helper()
65		dir = t.TempDir()
66		path = filepath.Join(dir, "registry.json")
67		writeRegistry(t, path, savedFailureRegistryJSON)
68		if err := os.Chtimes(path, failedSaveModTime, failedSaveModTime); err != nil {
69			t.Fatal(err)
70		}
71		reg, existed, err := Load(path)
72		if err != nil || !existed {
73			t.Fatalf("fixture registry must load: existed=%v err=%v", existed, err)
74		}
75		original = reg.Batches
76		if len(original) != 3 {
77			t.Fatalf("fixture registry must hold multiple batches, got %+v", original)
78		}
79		originalBytes, err = os.ReadFile(path)
80		if err != nil {
81			t.Fatal(err)
82		}
83		return dir, path, original, originalBytes
84	}
85	
86	// assertSaveFailure checks the contract every rejected mid-save save must
87	// honor towards its caller: a non-nil error that names the actual target path
88	// and carries the injected cause.
89	func assertSaveFailure(t *testing.T, err, cause error, path string) {
90		t.Helper()
91		if err == nil {
92			t.Fatal("Save must report the failed save to its caller")
93		}
94		if !errors.Is(err, cause) {
95			t.Errorf("error %v must carry the failure cause %v", err, cause)
96		}
97		msg := err.Error()
98		if !strings.Contains(msg, path) {
99			t.Errorf("error %q must name the target path %q", msg, path)
100		}
101		if !strings.Contains(msg, cause.Error()) {
102			t.Errorf("error %q must state the failure reason %q", msg, cause.Error())
103		}
104	}
105	
106	// assertExistingTargetUntouched verifies that the failed save behaved as if it
107	// never ran for the actual target: identical bytes, the pinned modification
108	// time, the original records in their original order when read back, no
109	// temporary file left anywhere under dir, and the caller's submitted records
110	// unchanged in content and order.
111	func assertExistingTargetUntouched(t *testing.T, dir, path string, original []Batch, originalBytes []byte, reg *Registry, submitted []Batch) {
112		t.Helper()
113		info, err := os.Stat(path)
114		if err != nil {
115			t.Fatalf("the original registry file must still exist: %v", err)
116		}
117		if !info.ModTime().Equal(failedSaveModTime) {
118			t.Errorf("failed save touched the target's modification time: got %v, want %v", info.ModTime(), failedSaveModTime)
119		}
120		after, err := os.ReadFile(path)
121		if err != nil {
122			t.Fatal(err)
123		}
124		if !bytes.Equal(after, originalBytes) {
125			t.Fatalf("failed save changed the target bytes:\nbefore %s\nafter  %s", originalBytes, after)
126		}
127		if bytes.Contains(after, []byte("NEW-")) {
128			t.Fatalf("part of the submitted content landed in the target: %s", after)
129		}
130		loaded, existed, err := Load(path)
131		if err != nil || !existed {
132			t.Fatalf("original registry must still be usable: existed=%v err=%v", existed, err)
133		}
134		assertBatchesEqual(t, loaded.Batches, original)
135		assertNoLeftoverTempFiles(t, dir)
136		assertBatchesEqual(t, reg.Batches, submitted)
137	}
138	
139	// The content write stops halfway through the new content. The save must
140	// abort, clean up its temporary file and leave the existing registry — the
141	// actual replacement target — byte-for-byte and timestamp-for-timestamp
142	// untouched, loading with exactly the original records.
143	func TestSaveWriteFailureKeepsExistingRegistryIntact(t *testing.T) {
144		dir, path, original, originalBytes := setupExistingRegistry(t)
145	
146		cause := errors.New("injected write failure: disk full")
147		writeAttempted := false
148		old := WriteTempContent
149		WriteTempContent = func(f *os.File, data []byte) (int, error) {
150			writeAttempted = true
151			// Part of the new content genuinely reaches the temporary file before
152			// the write fails, so the save aborts with the write incomplete.
153			half := len(data) / 2
154			if _, err := f.Write(data[:half]); err != nil {
155				return 0, err
156			}
157			return half, cause
158		}
159		t.Cleanup(func() { WriteTempContent = old })
160	
161		submitted := failureSubmission()
162		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
163		err := Save(path, reg)
164	
165		assertSaveFailure(t, err, cause, path)
166		if !writeAttempted {
167			t.Fatal("the save never reached the content write; the failure protection was not exercised")
168		}
169		assertExistingTargetUntouched(t, dir, path, original, originalBytes, reg, submitted)
170	}
171	
172	// The new content is fully prepared in the temporary file — the injected
173	// rename proves it by reading the complete new table, including the new
174	// batches, from the file it is asked to move — but the replacement of the
175	// target fails. The existing registry must survive exactly as it was and the
176	// prepared temporary file must be removed, not left behind as a would-be
177	// registry.
178	func TestSaveRenameFailureKeepsExistingRegistryIntact(t *testing.T) {
179		dir, path, original, originalBytes := setupExistingRegistry(t)
180	
181		cause := errors.New("injected rename failure: cannot replace target")
182		renameAttempted := false
183		old := RenameTempFile
184		RenameTempFile = func(oldpath, newpath string) error {
185			renameAttempted = true
186			if newpath != path {
187				t.Errorf("rename must target the actual save path %q, got %q", path, newpath)
188			}
189			prepared, err := os.ReadFile(oldpath)
190			if err != nil {
191				t.Errorf("the prepared content must be readable before the replacement: %v", err)
192				return cause
193			}
194			for _, marker := range []string{"OLD-1", "NEW-1", "NEW-2", "新产品"} {
195				if !bytes.Contains(prepared, []byte(marker)) {
196					t.Errorf("prepared content is missing %q; the save did not get the full new table ready: %s", marker, prepared)
197				}
198			}
199			return cause
200		}
201		t.Cleanup(func() { RenameTempFile = old })
202	
203		submitted := failureSubmission()
204		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
205		err := Save(path, reg)
206	
207		assertSaveFailure(t, err, cause, path)
208		if !renameAttempted {
209			t.Fatal("the save never reached the replacement step; the failure protection was not exercised")
210		}
211		assertExistingTargetUntouched(t, dir, path, original, originalBytes, reg, submitted)
212	}
213	
214	// The same two mid-save failures against a target that does not exist yet:
215	// the save must end with an error, the target must still not exist, no file
216	// holding part of the submitted batches may appear, and no temporary file may
217	// survive.
218	func TestSaveFailureOnMissingTargetLeavesNoFile(t *testing.T) {
219		injectWriteFailure := func(t *testing.T, cause error) {
220			old := WriteTempContent
221			WriteTempContent = func(f *os.File, data []byte) (int, error) {
222				half := len(data) / 2
223				if _, err := f.Write(data[:half]); err != nil {
224					return 0, err
225				}
226				return half, cause
227			}
228			t.Cleanup(func() { WriteTempContent = old })
229		}
230		injectRenameFailure := func(t *testing.T, cause error) {
231			old := RenameTempFile
232			RenameTempFile = func(oldpath, newpath string) error { return cause }
233			t.Cleanup(func() { RenameTempFile = old })
234		}
235		cases := []struct {
236			name   string
237			inject func(t *testing.T, cause error)
238		}{
239			{"content write incomplete", injectWriteFailure},
240			{"replacement refused", injectRenameFailure},
241		}
242		for _, tc := range cases {
243			t.Run(tc.name, func(t *testing.T) {
244				dir := t.TempDir()
245				path := filepath.Join(dir, "registry.json")
246				cause := errors.New("injected save failure")
247				tc.inject(t, cause)
248	
249				submitted := failureSubmission()
250				reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
251				err := Save(path, reg)
252	
253				assertSaveFailure(t, err, cause, path)
254				if _, statErr := os.Stat(path); !os.IsNotExist(statErr) {
255					t.Fatalf("failed save must not create the target file, stat err=%v", statErr)
256				}
257				entries, readErr := os.ReadDir(dir)
258				if readErr != nil {
259					t.Fatal(readErr)
260				}
261				if len(entries) != 0 {
262					t.Fatalf("failed save left files behind in the target directory: %v", entries)
263				}
264				assertNoLeftoverTempFiles(t, dir)
265				assertBatchesEqual(t, reg.Batches, submitted)
266			})
267		}
268	}
269	
270	// The success counterpart for the same legal submission: with no failure
271	// injected, Save replaces the existing registry — the bytes and the pinned
272	// modification time both change, the new content is really there — and the
273	// file reads back with all four public fields per record in submission order.
274	// This is what distinguishes a working failure protection from a save that
275	// never executed.
276	func TestSaveSuccessReplacesExistingRegistry(t *testing.T) {
277		dir, path, _, originalBytes := setupExistingRegistry(t)
278	
279		submitted := failureSubmission()
280		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
281		if err := Save(path, reg); err != nil {
282			t.Fatalf("the legal submission must save when nothing fails: %v", err)
283		}
284	
285		info, err := os.Stat(path)
286		if err != nil {
287			t.Fatal(err)
288		}
289		if info.ModTime().Equal(failedSaveModTime) {
290			t.Fatal("successful save must replace the file; the pinned modification time survived")
291		}
292		after, err := os.ReadFile(path)
293		if err != nil {
294			t.Fatal(err)
295		}
296		if bytes.Equal(after, originalBytes) {
297			t.Fatal("successful save must replace the old content; the original bytes survived")
298		}
299		for _, marker := range []string{"NEW-1", "NEW-2", "新产品"} {
300			if !bytes.Contains(after, []byte(marker)) {
301				t.Fatalf("saved file is missing the new content %q: %s", marker, after)
302			}
303		}
304	
305		loaded, existed, err := Load(path)
306		if err != nil || !existed {
307			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
308		}
309		if loaded.Version != FormatVersion {
310			t.Fatalf("read-back version = %d, want %d", loaded.Version, FormatVersion)
311		}
312		assertBatchesEqual(t, loaded.Batches, submitted)
313		assertNoLeftoverTempFiles(t, dir)
314		assertBatchesEqual(t, reg.Batches, submitted)
315	}
